    "question": "Examine the mechanistic route: The dehydration of butan-2-ol with concentrated H2SO4 at 443 K produces but-2-ene as the major product rather than but-1-ene. This regioselectivity is governed by:",
    "options": {
      "A": "Saytzeff's (Zaitsev's) rule",
      "B": "Hofmann's rule",
      "C": "Markovnikov's rule",
      "D": "Kharasch peroxide effect"
    },
    "optionsList": [
      "Saytzeff's (Zaitsev's) rule",
      "Hofmann's rule",
      "Markovnikov's rule",
      "Kharasch peroxide effect"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nSaytzeff elimination rule in alkene synthesis.\n\n2. GIVEN:\nDehydration of 2-butanol: CH3-CH(OH)-CH2-CH3 -[H2SO4, heat]-> but-2-ene (major) + but-1-ene (minor).\n\n3. FORMULA / PRINCIPLE:\nThe more substituted, thermodynamically more stable alkene is favored.\n\n4. STEP-BY-STEP SOLUTION:\n1. Dehydration proceeds via protonation of -OH followed by loss of H2O to give a 2\u00b0 carbocation: CH3-CH+-CH2-CH3.\n2. Loss of a beta-proton can occur from C-1 (giving but-1-ene with 2 alpha-H) or from C-3 (giving but-2-ene with 6 alpha-H).\n3. According to Saytzeff's rule, elimination preferentially yields the alkene with the greater number of alkyl substituents attached to the double bond.\n4. But-2-ene is stabilized by 6 hyperconjugative structures, making it the major product (~80%).\n\n5. FINAL ANSWER:\nOption A: Saytzeff's (Zaitsev's) rule\n\n6. WHY OTHER OPTIONS ARE WRONG:\nHofmann elimination produces the less substituted alkene when bulky bases or quaternary ammonium salts are used.",
    "solutionStructured": {
      "concept": "Saytzeff elimination rule in alkene synthesis.",
      "given": "Dehydration of 2-butanol: CH3-CH(OH)-CH2-CH3 -[H2SO4, heat]-> but-2-ene (major) + but-1-ene (minor).",
      "formula": "The more substituted, thermodynamically more stable alkene is favored.",
      "stepByStep": "1. Dehydration proceeds via protonation of -OH followed by loss of H2O to give a 2\u00b0 carbocation: CH3-CH+-CH2-CH3.\n2. Loss of a beta-proton can occur from C-1 (giving but-1-ene with 2 alpha-H) or from C-3 (giving but-2-ene with 6 alpha-H).\n3. According to Saytzeff's rule, elimination preferentially yields the alkene with the greater number of alkyl substituents attached to the double bond.\n4. But-2-ene is stabilized by 6 hyperconjugative structures, making it the major product (~80%).",
      "finalAnswer": "Option A: Saytzeff's (Zaitsev's) rule",
      "whyOtherOptionsWrong": "Hofmann elimination produces the less substituted alkene when bulky bases or quaternary ammonium salts are used."
    },
