    "explanation": "1. CONCEPT:\nStoichiometry of hydrocarbon combustion.\n\n2. GIVEN:\nCombustion equation: CxHy + (x + y/4) O2 -> x CO2 + (y/2) H2O.\n\n3. FORMULA / PRINCIPLE:\nGiven: x = 3 moles CO2; (x + y/4) = 5 moles O2.\n\n4. STEP-BY-STEP SOLUTION:\n1. Step 1: From the moles of CO2 produced, the number of carbon atoms is x = 3.\n2. Step 2: From the oxygen consumed: x + y/4 = 5.\n3. Step 3: Substitute x = 3: 3 + y/4 = 5 -> y/4 = 2 -> y = 8.\n4. Step 4: The molecular formula is C3H8, which corresponds to propane.\n5. Balanced equation: C3H8 + 5 O2 -> 3 CO2 + 4 H2O.\n\n5. FINAL ANSWER:\nOption A: Propane (C3H8)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nPropene C3H6 would require 3 + 6/4 = 4.5 O2; propyne C3H4 would require 3 + 4/4 = 4 O2.",
