    "question": "The combustion of one mole of a hydrocarbon CxHy requires 5 moles of O2 and produces 3 moles of CO2. The hydrocarbon is:",
    "options": {
      "A": "Propane (C3H8)",
      "B": "Propene (C3H6)",
      "C": "Propyne (C3H4)",
      "D": "Butane (C4H10)"
    },
