    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nAnomalous behaviour of halogens in electrophilic aromatic substitution.\n\n2. GIVEN:\nChlorobenzene C6H5Cl.\n\n3. FORMULA / PRINCIPLE:\n-I inductive deactivation vs +M resonance directing effect.\n\n4. STEP-BY-STEP SOLUTION:\n1. Halogens are unique substituents on benzene: they are ring deactivators yet ortho/para-directors.\n2. Due to high electronegativity, chlorine withdraws electrons through sigma bonds (-I effect), lowering the overall electron density and slowing the reaction rate relative to benzene.\n3. However, through its unshared 3p lone pairs, it donates electron density into the pi system (+M effect), specifically stabilizing positive charge at the ortho and para arenium intermediates.\n4. Consequently, substitution occurs at the ortho and para positions.\n\n5. FINAL ANSWER:\nOption A: The +M resonance donation of chlorine directs ortho/para, despite its overall -I deactivating effect\n\n6. WHY OTHER OPTIONS ARE WRONG:\nChlorine is deactivating due to -I > +M, but directs ortho/para because resonance stabilization operates exclusively at ortho/para positions.",
