    "explanation": "1. CONCEPT:\nStereoselective partial reduction of alkynes to alkenes.\n\n2. GIVEN:\nR-C#C-R' + H2 -[Lindlar]-> cis-alkene.\n\n3. FORMULA / PRINCIPLE:\nHeterogeneous catalytic syn-addition of H2 on poisoned palladium catalyst surface.\n\n4. STEP-BY-STEP SOLUTION:\n1. Lindlar's catalyst consists of palladium supported on calcium carbonate, deactivated (poisoned) with lead acetate and quinoline or sulphur.\n2. The catalyst poisons prevent further reduction of the alkene to an alkane.\n3. Hydrogen atoms are delivered simultaneously from the metal catalyst surface to the same face of the alkyne (syn-addition).\n4. This stereospecifically produces the cis-alkene (Z-alkene).\n5. Conversely, anti-reduction using sodium in liquid ammonia (Birch reduction) produces the trans-alkene.\n\n5. FINAL ANSWER:\nOption A: Lindlar's catalyst (Pd/CaCO3 poisoned with lead acetate and quinoline)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nLindlar's catalyst yields cis-alkenes via syn-addition; Na/liquid NH3 yields trans-alkenes via anti-addition.",
