    "question": "Which of the following cycloalkanes has the maximum angle strain according to Baeyer's strain theory?",
    "options": {
      "A": "Cyclopropane",
      "B": "Cyclobutane",
      "C": "Cyclopentane",
      "D": "Cyclohexane"
    },
