    "question": "The dehydration of butan-2-ol with concentrated H2SO4 at 443 K produces but-2-ene as the major product rather than but-1-ene. This regioselectivity is governed by:",
    "options": {
      "A": "Saytzeff's (Zaitsev's) rule",
      "B": "Hofmann's rule",
      "C": "Markovnikov's rule",
      "D": "Kharasch peroxide effect"
    },
